TEMPLATES = {
    '_macros.html': '{% macro badge(status) %}<span class="badge {{ status }}">{{ status|pretty }}</span>{% endmacro %}\n\n{% macro paginator(p, noun) %}\n<div class="pager">\n  <div>{% if p.total %}Showing {{ p.first }} to {{ p.last }} of {{ p.total }} {{ noun }}{% else %}No {{ noun }}{% endif %}</div>\n  {% if p.pages > 1 %}\n  <nav class="pages" aria-label="Pagination">\n    {% if p.prev %}<a href="{{ here(page=p.prev) }}">Prev</a>{% else %}<span class="off">Prev</span>{% endif %}\n    {% for n in p.window %}\n      {% if n is none %}<span class="gap">...</span>\n      {% elif n == p.page %}<span class="cur" aria-current="page">{{ n }}</span>\n      {% else %}<a href="{{ here(page=n) }}">{{ n }}</a>{% endif %}\n    {% endfor %}\n    {% if p.next %}<a href="{{ here(page=p.next) }}">Next</a>{% else %}<span class="off">Next</span>{% endif %}\n  </nav>\n  {% endif %}\n</div>\n{% endmacro %}\n\n{% macro sorth(label, key, f, cls) %}\n<th class="{{ cls }}"><a class="sort {{ f.dir if f.sort == key }}" href="{{ here(sort=key, dir=(\'desc\' if f.sort == key and f.dir == \'asc\' else \'asc\'), page=None) }}">{{ label }}</a></th>\n{% endmacro %}\n\n{% macro confirm(id, label, title, text, action, button, kind, fields) %}\n<button type="button" class="btn {{ kind }} sm" popovertarget="{{ id }}">{{ label }}</button>\n<div id="{{ id }}" popover class="panel">\n  <h3>{{ title }}</h3>\n  <p>{{ text }}</p>\n  <form method="post" action="{{ action }}">\n    {% for key, value in (fields or {}).items() %}<input type="hidden" name="{{ key }}" value="{{ value }}">{% endfor %}\n    <input type="hidden" name="next" value="{{ request.full_path.rstrip(\'?\') }}">\n    <div class="btn-row"><button class="btn {{ kind }}" type="submit">{{ button }}</button><button class="btn ghost" type="button" popovertarget="{{ id }}" popovertargetaction="hide">Cancel</button></div>\n  </form>\n</div>\n{% endmacro %}\n\n{% macro history_table(rows, f, show_teacher, can_close) %}\n{% if not rows %}\n<div class="empty"><b>No attendance records</b>Nothing matches yet. Try widening the filters.</div>\n{% else %}\n<div class="table-wrap"><table>\n  <thead><tr>\n    {% if show_teacher %}{{ sorth(\'Teacher\', \'teacher\', f) }}{% endif %}\n    {{ sorth(\'Room\', \'room\', f) }}{{ sorth(\'Time in\', \'time\', f) }}<th>Time out</th>{{ sorth(\'Duration\', \'duration\', f) }}{{ sorth(\'Status\', \'status\', f) }}\n    {% if can_close %}<th class="no-print"></th>{% endif %}\n  </tr></thead>\n  <tbody>\n  {% for a in rows %}\n  <tr>\n    {% if show_teacher %}<td>{{ a.teacher_name }}</td>{% endif %}\n    <td>{{ a.room_name }}</td><td>{{ a.time_in_text }}</td><td>{{ a.time_out_text }}</td>\n    <td>{% if a.status == \'ACTIVE\' %}{{ a.elapsed_text }} so far{% else %}{{ a.duration_text }}{% endif %}</td>\n    <td>{{ badge(a.status) }}</td>\n    {% if can_close %}<td class="no-print">{% if a.status == \'ACTIVE\' %}{{ confirm(\'close-\' ~ a.id, \'Close\', \'Close this record?\', a.teacher_name ~ \' will be marked incomplete and \' ~ a.room_name ~ \' becomes available again.\', url_for(\'admin_close\', attendance_id=a.id), \'Close record\', \'warn\', {}) }}{% endif %}</td>{% endif %}\n  </tr>\n  {% endfor %}\n  </tbody>\n</table></div>\n{% endif %}\n{% endmacro %}\n',
    'admin.html': '{% extends "layout.html" %}\n{% from "_macros.html" import history_table, confirm with context %}\n{% block title %}Overview{% endblock %}\n{% block crumb %}Overview{% endblock %}\n{% block content %}\n<div class="head">\n  <div><h1>Administrator overview</h1><p class="sub">A live look at attendance, rooms and accounts.</p></div>\n  <div class="btn-row"><a class="btn ghost" href="{{ url_for(\'admin_reports\') }}">Open reports</a><a class="btn" href="{{ url_for(\'admin_users\') }}">Manage users</a></div>\n</div>\n<div class="stats">\n  <div class="card stat"><div><strong>{{ stats.teachers }}</strong><span>Teachers</span></div></div>\n  <div class="card stat"><div><strong>{{ stats.staff }}</strong><span>Staff</span></div></div>\n  <div class="card stat"><div><strong>{{ stats.pending }}</strong><span>Pending approval</span></div></div>\n  <div class="card stat"><div><strong>{{ stats.in_use }}</strong><span>Rooms in use</span></div></div>\n  <div class="card stat"><div><strong>{{ stats.today }}</strong><span>Records today</span></div></div>\n</div>\n<div class="grid2">\n  <section class="card">\n    <div class="card-head"><h2>Records, last 7 days</h2><span class="hint">{{ week_total }} total</span></div>\n    <div class="bars" role="img" aria-label="Attendance records per day for the last seven days">\n      {% for d in chart %}\n      <div class="bar-col {{ \'today\' if d.today }}" title="{{ d.date }}: {{ d.n }}">\n        <div class="track" style="--h:{{ d.h }}%"><i style="animation-delay:{{ loop.index0 * 0.07 }}s"></i><b>{{ d.n }}</b></div>\n        <small>{{ d.label }}</small>\n      </div>\n      {% endfor %}\n    </div>\n  </section>\n  <section class="card">\n    <div class="card-head"><h2>Busiest rooms, 30 days</h2></div>\n    {% if rooms %}\n    <div class="hbars">\n      {% for r in rooms %}\n      <div class="hbar"><span>{{ r.name }}</span><div class="t"><i style="--w:{{ r.w }}%;animation-delay:{{ loop.index0 * 0.08 }}s"></i></div><em>{{ r.n }} classes, {{ r.time }}</em></div>\n      {% endfor %}\n    </div>\n    {% else %}<div class="empty"><b>No data yet</b>Room usage appears once classes are recorded.</div>{% endif %}\n  </section>\n</div>\n<div class="grid2">\n  <section class="card">\n    <div class="card-head"><h2 class="live">Active now</h2></div>\n    {% if active %}\n    <div class="table-wrap"><table>\n      <thead><tr><th>Teacher</th><th>Room</th><th>Elapsed</th><th class="no-print"></th></tr></thead>\n      <tbody>\n      {% for a in active %}\n      <tr><td>{{ a.teacher_name }}</td><td>{{ a.room_name }}</td><td>{{ a.elapsed_text }}</td>\n      <td class="no-print">{{ confirm(\'close-\' ~ a.id, \'Close\', \'Close this record?\', a.teacher_name ~ \' will be marked incomplete and \' ~ a.room_name ~ \' becomes available again.\', url_for(\'admin_close\', attendance_id=a.id), \'Close record\', \'warn\', {}) }}</td></tr>\n      {% endfor %}\n      </tbody>\n    </table></div>\n    {% else %}<div class="empty"><b>No class in session</b>Every room is free.</div>{% endif %}\n  </section>\n  <section class="card">\n    <div class="card-head"><h2>Waiting for approval</h2><a class="btn ghost sm" href="{{ url_for(\'admin_users\', status=\'INACTIVE\') }}">See all</a></div>\n    {% if pending %}\n    <div class="table-wrap"><table>\n      <tbody>\n      {% for u in pending %}\n      <tr>\n        <td><div class="cell-user"><span class="avatar">{{ u.initials }}</span><div>{{ u.full_name }}<small>{{ u.email }}</small></div></div></td>\n        <td>{{ u.role|capitalize }}</td>\n        <td><form method="post" action="{{ url_for(\'admin_status\', user_id=u.id) }}" class="inline"><input type="hidden" name="status" value="ACTIVE"><input type="hidden" name="next" value="{{ url_for(\'admin\') }}"><button class="btn ok sm" type="submit">Approve</button></form></td>\n      </tr>\n      {% endfor %}\n      </tbody>\n    </table></div>\n    {% else %}<div class="empty"><b>Nothing waiting</b>All sign-ups are handled.</div>{% endif %}\n  </section>\n</div>\n<section class="card">\n  <div class="card-head"><h2>Recent activity</h2><a class="btn ghost sm" href="{{ url_for(\'admin_reports\') }}">All records</a></div>\n  {% if recent %}\n  <ul class="feed">\n    {% for a in recent %}\n    <li>\n      <span class="dot {{ \'done\' if a.status == \'COMPLETED\' else (\'warn\' if a.status == \'INCOMPLETE\' else \'\') }}"></span>\n      <div><b>{{ a.teacher_name }}</b> in {{ a.room_name }}<small>{{ a.time_in_text }}{% if a.status != \'ACTIVE\' %} to {{ a.time_out_text }}{% endif %}</small></div>\n      <span class="badge {{ a.status }}">{{ a.status|pretty }}</span>\n    </li>\n    {% endfor %}\n  </ul>\n  {% else %}<div class="empty"><b>No activity yet</b>Records show up here as teachers time in.</div>{% endif %}\n</section>\n{% endblock %}\n',
    'admin_rooms.html': '{% extends "layout.html" %}\n{% from "_macros.html" import confirm, badge with context %}\n{% block title %}Rooms{% endblock %}\n{% block crumb %}Rooms{% endblock %}\n{% block content %}\n<div class="head">\n  <div><h1>Rooms and facilities</h1><p class="sub">Add rooms, rename them, and take them out of service for maintenance.</p></div>\n</div>\n<section class="card">\n  <div class="card-head"><h2>Add a room</h2></div>\n  <form method="post" action="{{ url_for(\'admin_room_add\') }}">\n    <div class="form-grid">\n      <label class="field">Code<input name="code" placeholder="RM-201" required></label>\n      <label class="field">Room name<input name="name" required></label>\n      <label class="field">Building<input name="building" required></label>\n      <label class="field">Floor<input name="floor"></label>\n      <label class="field">Capacity<input name="capacity" type="number" min="0"></label>\n    </div>\n    <button class="btn" type="submit">Add room</button>\n  </form>\n</section>\n<section class="card">\n  <div class="card-head"><h2>All rooms</h2><span class="hint">{{ rooms|length }} total</span></div>\n  {% if rooms %}\n  <div class="table-wrap"><table>\n    <thead><tr><th>Code</th><th>Room</th><th>Building</th><th>Floor</th><th class="num">Capacity</th><th class="num">Uses</th><th>Status</th><th class="no-print">Actions</th></tr></thead>\n    <tbody>\n    {% for r in rooms %}\n    <tr>\n      <td>{{ r.code }}</td>\n      <td>{{ r.name }}{% if r.occupant %}<small class="hint" style="display:block">In use by {{ r.occupant }}</small>{% endif %}</td>\n      <td>{{ r.building }}</td><td>{{ r.floor or \'-\' }}</td><td class="num">{{ r.capacity }}</td><td class="num">{{ r.uses }}</td>\n      <td>{{ badge(r.status) }}</td>\n      <td class="no-print"><div class="btn-row">\n        <button class="btn ghost sm" type="button" popovertarget="edit-{{ r.id }}">Edit</button>\n        {% if r.refs or r.status == \'OCCUPIED\' %}<button class="btn ghost sm" type="button" disabled title="Has attendance history. Set it to inactive instead.">Delete</button>\n        {% else %}{{ confirm(\'delete-\' ~ r.id, \'Delete\', \'Delete this room?\', r.name ~ \' has never been used, so it will be removed permanently.\', url_for(\'admin_room_delete\', room_id=r.id), \'Delete room\', \'danger\', {}) }}{% endif %}\n      </div>\n      <div id="edit-{{ r.id }}" popover class="panel" style="width:min(560px,calc(100vw - 2rem))">\n        <h3>Edit {{ r.code }}</h3>\n        <p>{% if r.status == \'OCCUPIED\' %}This room is in use, so its status cannot change until the class ends.{% else %}Set the status to maintenance or inactive to hide the room from teachers.{% endif %}</p>\n        <form method="post" action="{{ url_for(\'admin_room_update\', room_id=r.id) }}">\n          <div class="form-grid">\n            <label class="field">Room name<input name="name" value="{{ r.name }}" required></label>\n            <label class="field">Building<input name="building" value="{{ r.building }}" required></label>\n            <label class="field">Floor<input name="floor" value="{{ r.floor }}"></label>\n            <label class="field">Capacity<input name="capacity" type="number" min="0" value="{{ r.capacity }}"></label>\n            <label class="field wide">Status\n              <select name="status" {% if r.status == \'OCCUPIED\' %}disabled{% endif %}>\n                {% for s in (\'AVAILABLE\', \'MAINTENANCE\', \'INACTIVE\') %}<option value="{{ s }}" {{ \'selected\' if r.status == s }}>{{ s|pretty|capitalize }}</option>{% endfor %}\n                {% if r.status == \'OCCUPIED\' %}<option selected>Occupied</option>{% endif %}\n              </select>\n            </label>\n          </div>\n          <div class="btn-row"><button class="btn" type="submit">Save changes</button><button class="btn ghost" type="button" popovertarget="edit-{{ r.id }}" popovertargetaction="hide">Cancel</button></div>\n        </form>\n      </div></td>\n    </tr>\n    {% endfor %}\n    </tbody>\n  </table></div>\n  {% else %}<div class="empty"><b>No rooms yet</b>Add the first room above.</div>{% endif %}\n</section>\n{% endblock %}\n',
    'admin_users.html': '{% extends "layout.html" %}\n{% from "_macros.html" import paginator, sorth, confirm, badge with context %}\n{% block title %}Users{% endblock %}\n{% block crumb %}Users{% endblock %}\n{% block content %}\n<div class="head">\n  <div><h1>User accounts</h1><p class="sub">Approve sign-ups, suspend accounts, reset passwords and add people directly.</p></div>\n  <div class="btn-row"><button class="btn" type="button" popovertarget="new-user">New user</button></div>\n</div>\n<div id="new-user" popover class="panel" style="width:min(560px,calc(100vw - 2rem))">\n  <h3>Add a user</h3>\n  <p>The account is active straight away, with no approval step.</p>\n  <form method="post" action="{{ url_for(\'admin_user_create\') }}">\n    <input type="hidden" name="next" value="{{ request.full_path.rstrip(\'?\') }}">\n    <div class="form-grid">\n      <label class="field">Role<select name="role"><option value="teacher">Teacher</option><option value="staff">School staff</option></select></label>\n      <label class="field">ID number<input name="employee_no" required></label>\n      <label class="field">First name<input name="first_name" required></label>\n      <label class="field">Last name<input name="last_name" required></label>\n      <label class="field wide">Email<input type="email" name="email" required></label>\n      <label class="field wide">Temporary password<input type="text" name="password" minlength="8" autocomplete="off" required><span class="hint">At least 8 characters. Share it with the person and ask them to change it from Profile.</span></label>\n    </div>\n    <div class="btn-row"><button class="btn" type="submit">Create account</button><button class="btn ghost" type="button" popovertarget="new-user" popovertargetaction="hide">Cancel</button></div>\n  </form>\n</div>\n<section class="card">\n  <form method="get" class="filters no-print">\n    <input type="hidden" name="sort" value="{{ f.sort }}"><input type="hidden" name="dir" value="{{ f.dir }}">\n    <label class="field grow">Search<input name="q" value="{{ f.q }}" placeholder="Name, email or ID number"></label>\n    <label class="field">Role<select name="role"><option value="">All roles</option><option value="teacher" {{ \'selected\' if f.role == \'teacher\' }}>Teachers</option><option value="staff" {{ \'selected\' if f.role == \'staff\' }}>Staff</option></select></label>\n    <label class="field">Status\n      <select name="status">\n        <option value="">All statuses</option>\n        {% for s in (\'ACTIVE\', \'INACTIVE\', \'SUSPENDED\') %}<option value="{{ s }}" {{ \'selected\' if f.status == s }}>{{ \'Pending\' if s == \'INACTIVE\' else s|pretty|capitalize }}</option>{% endfor %}\n      </select>\n    </label>\n    <div class="btn-row"><button class="btn" type="submit">Apply</button><a class="btn ghost" href="{{ url_for(\'admin_users\') }}">Reset</a></div>\n  </form>\n  {% if users %}\n  <div class="table-wrap"><table>\n    <thead><tr>{{ sorth(\'Name\', \'name\', f) }}{{ sorth(\'ID number\', \'id\', f) }}{{ sorth(\'Role\', \'role\', f) }}{{ sorth(\'Status\', \'status\', f) }}<th>Last login</th><th class="no-print">Actions</th></tr></thead>\n    <tbody>\n    {% for u in users %}\n    {% set next = {\'ACTIVE\': (\'SUSPENDED\', \'Suspend\', \'warn\'), \'INACTIVE\': (\'ACTIVE\', \'Approve\', \'ok\'), \'SUSPENDED\': (\'ACTIVE\', \'Reactivate\', \'ok\')}[u.status] %}\n    <tr>\n      <td><div class="cell-user"><span class="avatar">{{ u.initials }}</span><div>{{ u.full_name }}<small>{{ u.email }}</small></div></div></td>\n      <td>{{ u.employee_no }}</td>\n      <td><span class="badge">{{ u.role }}</span></td>\n      <td>{{ badge(u.status) }}</td>\n      <td>{{ u.last_login_text }}</td>\n      <td class="no-print"><div class="btn-row">\n        <form method="post" action="{{ url_for(\'admin_status\', user_id=u.id) }}" class="inline"><input type="hidden" name="status" value="{{ next[0] }}"><input type="hidden" name="next" value="{{ request.full_path.rstrip(\'?\') }}"><button class="btn sm {{ next[2] }}" type="submit">{{ next[1] }}</button></form>\n        {{ confirm(\'reset-\' ~ u.id, \'Reset password\', \'Reset this password?\', u.full_name ~ \' will be signed out everywhere and given a new temporary password, shown once.\', url_for(\'admin_reset\', user_id=u.id), \'Reset password\', \'warn\', {}) }}\n        {% if u.refs %}<button class="btn ghost sm" type="button" disabled title="Has attendance history. Suspend instead.">Delete</button>\n        {% else %}{{ confirm(\'delete-\' ~ u.id, \'Delete\', \'Delete this account?\', u.full_name ~ \' has no attendance history, so the account will be removed permanently.\', url_for(\'admin_delete\', user_id=u.id), \'Delete account\', \'danger\', {}) }}{% endif %}\n      </div></td>\n    </tr>\n    {% endfor %}\n    </tbody>\n  </table></div>\n  {% else %}<div class="empty"><b>No accounts match</b>Try a different search or clear the filters.</div>{% endif %}\n  {{ paginator(pager, \'accounts\') }}\n</section>\n{% endblock %}\n',
    'base.html': '<!DOCTYPE html>\n<html lang="en" data-theme="{{ theme }}">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>{% block title %}QR Attendance{% endblock %} - QR Attendance</title>\n<meta name="theme-color" content="#11305c">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">\n<link rel="icon" href="{{ url_for(\'static\', filename=\'favicon.ico\') }}" sizes="any">\n<link rel="icon" type="image/png" sizes="32x32" href="{{ url_for(\'static\', filename=\'img/favicon-32.png\') }}">\n<link rel="icon" type="image/png" sizes="16x16" href="{{ url_for(\'static\', filename=\'img/favicon-16.png\') }}">\n<link rel="apple-touch-icon" href="{{ url_for(\'static\', filename=\'img/apple-touch-icon.png\') }}">\n<link rel="manifest" href="{{ url_for(\'static\', filename=\'site.webmanifest\') }}">\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'app.css\') }}">\n{% block head %}{% endblock %}\n</head>\n<body class="enter">\n<a class="skip" href="#main">Skip to content</a>\n{% with messages = get_flashed_messages(with_categories=true) %}\n{% if messages %}\n<div class="flashes" role="status">\n  {% for category, message in messages %}\n  <div class="flash {{ \'ok\' if category in (\'ok\', \'sticky\') }} {{ \'sticky\' if category == \'sticky\' }}">\n    <b>{{ \'Done\' if category in (\'ok\', \'sticky\') else \'Heads up\' }}</b>\n    {% if category == \'sticky\' %}{{ message.rsplit(\': \', 1)[0] }}: <code>{{ message.rsplit(\': \', 1)[1] }}</code>{% else %}{{ message }}{% endif %}\n  </div>\n  {% endfor %}\n</div>\n{% endif %}\n{% endwith %}\n{% block body %}{% endblock %}\n</body>\n</html>\n',
    'error.html': '{% extends "base.html" %}\n{% block title %}{{ title }}{% endblock %}\n{% block body %}\n<main class="center-page" id="main">\n  <div>\n    <img class="logo" style="margin:0 auto 1rem;width:56px;height:56px" src="{{ url_for(\'static\', filename=\'img/logo-mark-128.png\') }}" alt="">\n    <h1>{{ code }}</h1>\n    <h2 style="justify-content:center">{{ title }}</h2>\n    <p>{{ text }}</p>\n    <a class="btn" href="{{ url_for(\'index\') }}">Back to the start</a>\n  </div>\n</main>\n{% endblock %}\n',
    'history.html': '{% extends "layout.html" %}\n{% from "_macros.html" import history_table, paginator with context %}\n{% block title %}{{ title }}{% endblock %}\n{% block crumb %}{{ title }}{% endblock %}\n{% block content %}\n<div class="head">\n  <div><h1>{{ title }}</h1><p class="sub">Search, sort and export attendance. Times are shown in {{ tz_name }}. Use your browser\'s print command for a paper copy.</p></div>\n  <div class="btn-row no-print"><a class="btn ghost" href="{{ url_for(\'report\', **request.args) }}">Download CSV</a></div>\n</div>\n<section class="card">\n  <div class="chips no-print">\n    <a class="chip {{ \'on\' if not f.start and not f.end }}" href="{{ here(start=None, end=None, page=None) }}">All time</a>\n    {% for p in presets %}<a class="chip {{ \'on\' if p.on }}" href="{{ here(start=p.start, end=p.end, page=None) }}">{{ p.label }}</a>{% endfor %}\n  </div>\n  <form method="get" class="filters no-print">\n    <input type="hidden" name="sort" value="{{ f.sort }}"><input type="hidden" name="dir" value="{{ f.dir }}">\n    <label class="field grow">Search<input name="q" value="{{ f.q }}" placeholder="Teacher or room"></label>\n    <label class="field">Status\n      <select name="status">\n        <option value="">All statuses</option>\n        {% for s in (\'ACTIVE\', \'COMPLETED\', \'INCOMPLETE\') %}<option value="{{ s }}" {{ \'selected\' if f.status == s }}>{{ s|pretty|capitalize }}</option>{% endfor %}\n      </select>\n    </label>\n    <label class="field">Room\n      <select name="room">\n        <option value="">All rooms</option>\n        {% for r in rooms %}<option value="{{ r.id }}" {{ \'selected\' if f.room == r.id|string }}>{{ r.name }}</option>{% endfor %}\n      </select>\n    </label>\n    <label class="field">From<input type="date" name="start" value="{{ f.start }}"></label>\n    <label class="field">To<input type="date" name="end" value="{{ f.end }}"></label>\n    <div class="btn-row"><button class="btn" type="submit">Apply</button><a class="btn ghost" href="{{ url_for(request.endpoint) }}">Reset</a></div>\n  </form>\n  {{ history_table(rows, f, show_teacher, can_close) }}\n  {{ paginator(pager, \'records\') }}\n</section>\n{% endblock %}\n',
    'layout.html': '{% extends "base.html" %}\n{% block body %}\n<input type="checkbox" id="nav-toggle" class="nav-toggle" aria-hidden="true" tabindex="-1">\n<div class="shell">\n  <aside class="sidebar" aria-label="Main navigation">\n    <div class="side-brand">\n      <a class="brand" href="{{ url_for(g.user.role) }}"><img class="logo" src="{{ url_for(\'static\', filename=\'img/logo-mark-128.png\') }}" alt="">QR Attendance</a>\n    </div>\n    <div>\n      <div class="nav-title">{{ g.user.role|capitalize }} menu</div>\n      <nav class="nav">\n        {% for item in nav %}\n        <a href="{{ url_for(item.endpoint) }}" {% if item.active %}aria-current="page"{% endif %}>{{ item.label }}{% if item.endpoint == \'admin_users\' and pending_count %}<span class="count">{{ pending_count }}</span>{% endif %}</a>\n        {% endfor %}\n      </nav>\n    </div>\n    <div class="side-foot">\n      <div class="side-user">\n        <span class="avatar">{{ initials }}</span>\n        <div><b>{{ g.user.first_name }} {{ g.user.last_name }}</b><small>{{ g.user.role }}</small></div>\n      </div>\n      <form method="post" action="{{ url_for(\'logout\') }}"><button class="btn ghost block" type="submit">Log out</button></form>\n    </div>\n  </aside>\n  <label for="nav-toggle" class="scrim"></label>\n  <div class="main">\n    <header class="top">\n      <div class="top-left">\n        <label for="nav-toggle" class="burger" aria-label="Open menu"><span></span><span></span><span></span></label>\n        <div class="crumbs">QR Attendance / <b>{% block crumb %}{% endblock %}</b></div>\n      </div>\n      <div class="top-right">\n        <span class="clock">{{ today_text }}</span>\n        <form method="post" action="{{ url_for(\'theme\') }}">\n          <input type="hidden" name="mode" value="cycle">\n          <input type="hidden" name="next" value="{{ request.full_path.rstrip(\'?\') }}">\n          <button class="theme-btn" type="submit" title="Switch theme">Theme: {{ \'Auto\' if theme == \'system\' else theme|capitalize }}</button>\n        </form>\n        <button class="userchip" type="button" popovertarget="usermenu"><span class="avatar">{{ initials }}</span><span class="nm">{{ g.user.first_name }}</span></button>\n      </div>\n      <div id="usermenu" popover class="menu">\n        <div class="who-line"><b>{{ g.user.first_name }} {{ g.user.last_name }}</b>{{ g.user.email }}</div>\n        <a href="{{ url_for(\'profile\') }}">Profile and password</a>\n        <hr>\n        <form method="post" action="{{ url_for(\'logout\') }}"><button type="submit">Log out</button></form>\n      </div>\n    </header>\n    <main id="main" class="content">\n      {% block content %}{% endblock %}\n    </main>\n  </div>\n</div>\n{% endblock %}\n',
    'login.html': '{% extends "base.html" %}\n{% block title %}Sign in{% endblock %}\n{% block body %}\n<main class="auth" id="main">\n  <aside class="auth-side">\n    <div class="blocks" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>\n    <svg class="hero-logo" viewBox="0 0 238 238" aria-hidden="true">\n      <rect x="0" y="0" width="100" height="100" rx="22" fill="#e8f0fd"/>\n      <rect x="138" y="0" width="100" height="100" rx="22" fill="#6fa3ef"/>\n      <rect x="0" y="138" width="100" height="100" rx="22" fill="#6fa3ef"/>\n      <rect x="138" y="138" width="46" height="46" rx="12" fill="#e8f0fd"/>\n      <rect x="192" y="192" width="46" height="46" rx="12" fill="#e8f0fd"/>\n    </svg>\n    <div class="brand light"><img class="logo" src="{{ url_for(\'static\', filename=\'img/logo-mark-128.png\') }}" alt="">QR Attendance</div>\n    <h1>Teacher attendance and room monitoring</h1>\n    <ul>\n      <li><span>Teachers generate a short-lived QR code for the room they are using.</span></li>\n      <li><span>Staff scan the code to record Time In, and teachers press Time Out when class ends.</span></li>\n      <li><span>Administrators manage accounts and rooms, and review, filter and export attendance reports.</span></li>\n    </ul>\n  </aside>\n  <section class="auth-main">\n    <form class="theme-corner" method="post" action="{{ url_for(\'theme\') }}">\n      <input type="hidden" name="mode" value="cycle">\n      <input type="hidden" name="next" value="{{ request.full_path.rstrip(\'?\') }}">\n      <button class="theme-btn" type="submit">Theme: {{ \'Auto\' if theme == \'system\' else theme|capitalize }}</button>\n    </form>\n    <div class="auth-card">\n      <h1><img src="{{ url_for(\'static\', filename=\'img/logo-mark-128.png\') }}" alt="">Welcome</h1>\n      <p class="sub">Sign in or create an account to continue.</p>\n      <div class="tabs">\n        <a href="{{ url_for(\'index\') }}" class="{{ \'on\' if mode == \'login\' }}">Log in</a>\n        <a href="{{ url_for(\'index\', mode=\'signup\') }}" class="{{ \'on\' if mode == \'signup\' }}">Sign up</a>\n      </div>\n      {% if mode == \'login\' %}\n      <form method="post" action="{{ url_for(\'login\') }}">\n        <label class="field">Role\n          <select name="role">\n            <option value="teacher">Teacher</option>\n            <option value="staff">School staff</option>\n            <option value="admin">Administrator</option>\n          </select>\n        </label>\n        <label class="field">Email<input type="email" name="email" autocomplete="email" required></label>\n        <label class="field">Password<input type="password" name="password" autocomplete="current-password" required></label>\n        <button class="btn block" type="submit">Log in</button>\n      </form>\n      {% else %}\n      <form method="post" action="{{ url_for(\'register\') }}">\n        <label class="field">Role\n          <select name="role">\n            <option value="teacher">Teacher</option>\n            <option value="staff">School staff</option>\n          </select>\n        </label>\n        <label class="field">ID number<input name="employee_no" autocomplete="off" required></label>\n        <div class="row2">\n          <label class="field">First name<input name="first_name" autocomplete="given-name" required></label>\n          <label class="field">Last name<input name="last_name" autocomplete="family-name" required></label>\n        </div>\n        <label class="field">Email<input type="email" name="email" autocomplete="email" required></label>\n        <label class="field">Password<input type="password" name="password" autocomplete="new-password" minlength="8" required><span class="hint">At least 8 characters. Staff accounts wait for administrator approval.</span></label>\n        <button class="btn block" type="submit">Create account</button>\n      </form>\n      {% endif %}\n      {% if demo and mode == \'login\' %}\n      <details class="demo">\n        <summary>Demo accounts</summary>\n        <div class="btn-row">\n          {% for account in demo %}\n          <form method="post" action="{{ url_for(\'demo_login\', role=account.role) }}"><button class="btn ghost sm" type="submit">Sign in as {{ account.role }}</button></form>\n          {% endfor %}\n        </div>\n      </details>\n      {% endif %}\n    </div>\n  </section>\n</main>\n{% endblock %}\n',
    'profile.html': '{% extends "layout.html" %}\n{% block title %}Profile{% endblock %}\n{% block crumb %}Profile{% endblock %}\n{% block content %}\n<div class="head">\n  <div><h1>Profile</h1><p class="sub">Your account details, password and appearance.</p></div>\n</div>\n<div class="grid2">\n  <section class="card">\n    <div class="profile-head">\n      <span class="avatar lg">{{ initials }}</span>\n      <div><h2>{{ g.user.first_name }} {{ g.user.last_name }}</h2><span class="badge">{{ g.user.role }}</span></div>\n    </div>\n    <dl class="kv">\n      <dt>Email</dt><dd>{{ g.user.email }}</dd>\n      <dt>ID number</dt><dd>{{ employee_no }}</dd>\n      <dt>Member since</dt><dd>{{ joined }}</dd>\n      <dt>Previous login</dt><dd>{{ last_login }}</dd>\n    </dl>\n  </section>\n  <section class="card">\n    <div class="card-head"><h2>Your name</h2></div>\n    <form method="post" action="{{ url_for(\'profile_update\') }}">\n      <div class="row2">\n        <label class="field">First name<input name="first_name" value="{{ g.user.first_name }}" required></label>\n        <label class="field">Last name<input name="last_name" value="{{ g.user.last_name }}" required></label>\n      </div>\n      <button class="btn" type="submit">Save name</button>\n    </form>\n  </section>\n</div>\n<div class="grid2">\n  <section class="card">\n    <div class="card-head"><h2>Change password</h2></div>\n    <form method="post" action="{{ url_for(\'profile_password\') }}">\n      <label class="field">Current password<input type="password" name="current" autocomplete="current-password" required></label>\n      <label class="field">New password<input type="password" name="new" autocomplete="new-password" minlength="8" required><span class="hint">At least 8 characters.</span></label>\n      <label class="field">Confirm new password<input type="password" name="confirm" autocomplete="new-password" minlength="8" required></label>\n      <button class="btn" type="submit">Change password</button>\n    </form>\n  </section>\n  <section class="card">\n    <div class="card-head"><h2>Appearance</h2></div>\n    <p class="sub" style="margin-bottom:1rem">Auto follows your device setting.</p>\n    <form method="post" action="{{ url_for(\'theme\') }}" class="seg">\n      <input type="hidden" name="next" value="{{ url_for(\'profile\') }}">\n      {% for key, label in ((\'system\', \'Auto\'), (\'light\', \'Light\'), (\'dark\', \'Dark\')) %}\n      <button type="submit" name="mode" value="{{ key }}" class="{{ \'on\' if theme == key }}">{{ label }}</button>\n      {% endfor %}\n    </form>\n  </section>\n</div>\n{% endblock %}\n',
    'staff.html': '{% extends "layout.html" %}\n{% from "_macros.html" import history_table with context %}\n{% block title %}Scan{% endblock %}\n{% block crumb %}Scan{% endblock %}\n{% block head %}<script src="{{ url_for(\'static\', filename=\'scan.js\') }}" defer></script>{% endblock %}\n{% block content %}\n<div class="head">\n  <div><h1>Staff dashboard</h1><p class="sub">Scan a teacher\'s QR code to record Time In and monitor rooms in use.</p></div>\n</div>\n<div class="stats">\n  <div class="card stat"><div><strong>{{ in_use|length }}</strong><span>Rooms in use now</span></div></div>\n  <div class="card stat"><div><strong>{{ today_count }}</strong><span>Scans today</span></div></div>\n</div>\n<div class="cols">\n  <section class="card no-print">\n    <h2>Scan QR code</h2>\n    <video id="scanVideo" hidden playsinline muted style="width:100%;border-radius:12px;margin-bottom:.75rem;background:#000"></video>\n    <div class="btn-row" style="margin-bottom:.75rem">\n      <button class="btn" type="button" id="scanStart">Start camera</button>\n    </div>\n    <label class="field">Or choose a photo of the QR code\n      <input type="file" id="scanFile" accept="image/*" capture="environment">\n    </label>\n    <p class="sub" id="scanNote"></p>\n    <form method="post" action="{{ url_for(\'staff_scan\') }}" class="stack" id="scanForm">\n      <label class="field">Or enter the code manually\n        <div style="display:flex;gap:.5rem"><input name="token" id="scanToken" placeholder="Paste the QR code text" autocomplete="off" required><button class="btn" type="submit">Submit</button></div>\n      </label>\n    </form>\n  </section>\n  <section class="card">\n    <h2 class="live">Rooms in use</h2>\n    {% if in_use %}\n    <div class="table-wrap"><table>\n      <thead><tr><th>Room</th><th>Teacher</th><th>Since</th><th>Elapsed</th></tr></thead>\n      <tbody>{% for a in in_use %}<tr><td>{{ a.room_name }}</td><td>{{ a.teacher_name }}</td><td>{{ a.time_in_text }}</td><td>{{ a.elapsed_text }}</td></tr>{% endfor %}</tbody>\n    </table></div>\n    {% else %}<div class="empty"><b>All rooms are free</b>No class is in session right now.</div>{% endif %}\n  </section>\n</div>\n<section class="card" style="margin-top:1.25rem">\n  <div class="card-head"><h2>Today\'s scans</h2><a class="btn ghost sm" href="{{ url_for(\'history\') }}">Full history</a></div>\n  {% set f = {\'sort\': \'time\', \'dir\': \'desc\'} %}\n  {{ history_table(recent, f, true, false) }}\n</section>\n{% endblock %}\n',
    'teacher.html': '{% extends "layout.html" %}\n{% from "_macros.html" import history_table, confirm with context %}\n{% block title %}Dashboard{% endblock %}\n{% block crumb %}Dashboard{% endblock %}\n{% block head %}{% if qr or current %}<meta http-equiv="refresh" content="30">{% endif %}{% endblock %}\n{% block content %}\n<div class="head">\n  <div><h1>Hello, {{ g.user.first_name }}</h1><p class="sub">Pick a room, generate a QR code, and show it to staff to time in.</p></div>\n</div>\n<div class="stats">\n  <div class="card stat"><div><strong>{{ summary.week_classes }}</strong><span>Classes this week</span></div></div>\n  <div class="card stat"><div><strong>{{ summary.week_time }}</strong><span>Teaching time this week</span></div></div>\n  <div class="card stat"><div><strong>{{ summary.average }}</strong><span>Average class length</span></div></div>\n  <div class="card stat"><div><strong>{{ summary.all_classes }}</strong><span>All-time classes</span></div></div>\n</div>\n<div class="cols">\n  <section class="card">\n    {% if current %}\n    <h2 class="live">Currently in class</h2>\n    <div class="live-card">\n      <div><span class="sub">Room</span><div class="big" style="font-size:1.3rem">{{ current.room_name }}</div></div>\n      <div><span class="sub">Time in</span><div><b>{{ current.time_in_text }}</b></div></div>\n      <div><span class="sub">Elapsed</span><div class="big">{{ current.elapsed_text }}</div></div>\n      <div class="bar fill" style="--w:{{ [current.elapsed_minutes / 90 * 100, 100]|min|round|int }}%"><i></i></div>\n      <span class="hint">Bar fills over a 90 minute class. This page refreshes every 30 seconds.</span>\n      {{ confirm(\'timeout\', \'Time out\', \'End this class?\', \'Your Time Out is recorded now and \' ~ current.room_name ~ \' becomes available for others.\', url_for(\'teacher_timeout\'), \'Time out now\', \'warn\', {}) }}\n    </div>\n    {% else %}\n    <h2>Generate QR code</h2>\n    <form method="post" action="{{ url_for(\'teacher_qr\') }}">\n      <label class="field">Room or facility\n        <select name="room_id" required>\n          {% for r in rooms %}<option value="{{ r.id }}">{{ r.name }} - {{ r.building }}</option>{% else %}<option value="">No rooms available</option>{% endfor %}\n        </select>\n      </label>\n      <button class="btn block" type="submit" {% if not rooms %}disabled{% endif %}>Generate QR code</button>\n    </form>\n    {% if qr %}\n    <div class="qr-box">\n      <div class="qr"><img src="{{ qr.image }}" alt="Attendance QR code"></div>\n      <div class="bar"><i style="animation-delay:-{{ 300 - qr.seconds }}s"></i></div>\n      <div class="timer">Expires in {{ qr.seconds // 60 }}:{{ \'%02d\' % (qr.seconds % 60) }}</div>\n      <div class="code">{{ qr.token }}</div>\n      <p class="sub">Staff scan this code to record your Time In.</p>\n      <form method="post" action="{{ url_for(\'teacher_qr_cancel\') }}"><button class="btn ghost sm" type="submit">Cancel code</button></form>\n    </div>\n    {% endif %}\n    {% endif %}\n  </section>\n  <section class="card">\n    <div class="card-head"><h2>Recent attendance</h2><a class="btn ghost sm" href="{{ url_for(\'history\') }}">View all</a></div>\n    {% set f = {\'sort\': \'time\', \'dir\': \'desc\'} %}\n    {{ history_table(recent, f, false, false) }}\n  </section>\n</div>\n{% endblock %}\n',
}
